return "# 编队相关协议(12***)\n\n\n# 获取主线队伍列表\nget_player_arrays 12000 {\n    response {\n        arrays 0 : *battle_array\n    }\n}\n\nadd_array 12001 {\n    response {\n        result 0 : integer\n        array 1 : battle_array\n        diamond 2 : integer\n    }\n}\n\n# 获取积分赛队伍\nget_scorearena_battlearray 12002 {\n    request {\n        default 0 : integer     #客户端记录的上次积分赛队伍，仅用于积分赛队伍初始化\n    }\n    response {\n        result 0 : integer\n        array 1 : battle_array\n    }\n}\n\n# 更新队伍里的魂姬\nupdate_array_fightgirl 12003 {\n    request {\n        id 0 : integer\n        pos 1 : integer\n        servantid 2 : integer\n    }\n    response {\n        result 0 : integer\n        array 1 : battle_array\n    }\n}\n\n# 更新队伍里的魂器\nupdate_array_assistgirl 12004 {\n    request {\n        id 0 : integer\n        pos 1 : integer\n        assistgirl 2 : integer\n    }\n    response {\n        result 0 : integer\n        array 1 : battle_array\n    }\n}\n\nset_hangup_array 12005 {\n    request {\n        id 0 : integer\n    }\n    response {\n        result 0 : integer\n        cur_array 1 : integer\n    }\n}\n\n#一键设置编队\nupdate_array_onekey 12007 {\n    request {\n        id      0 : integer\n        battlearray 1 : battle_array\n    }\n    response {\n        result  0 : integer\n        array   1 : battle_array\n    }\n}\n\n#设置试炼编队\nget_adventure_battlearray 12010 {\n    request {\n        mode 0 : integer\n        default 1 : integer\n    }\n    response {\n        result 0 : integer\n        array 1 : battle_array\n    }\n}\n\nupdate_adventure_array_fightgirl 12011 {\n    request {\n        mode 0 : integer\n        pos 1 : integer\n        servantid 2 : integer\n    }\n    response {\n        result 0 : integer\n        array 1 : battle_array\n    }\n}\n\nupdate_adventure_array_assistgirl 12012 {\n    request {\n        mode 0 : integer\n        pos 1 : integer\n        assistgirl 2 : integer\n    }\n    response {\n        result 0 : integer\n        array 1 : battle_array\n    }\n}\n\nupdate_adventure_array_onekey 12013 {\n    request {\n        mode 0 : integer\n        battlearray 1 : battle_array\n    }\n    response {\n        result 0 : integer\n        array 1 : battle_array\n    }\n}\n\n# 更新队伍的助战魂姬\nupdate_array_assist 12014 {\n    request {\n        id 0 : integer\n        assist 1 : array_assist_config\n    }\n    response {\n        result 0 : integer # 1 成功 2 队伍不存在 3 助战学员不存在 4 助战学员正在出战 5 助战学员职业不符合 6 助阵已满\n    }\n}\n\n# 更新试炼队伍的助战魂姬\nupdate_adventure_array_assist 12015 {\n    request {\n        mode 0 : integer\n        assist 1 : array_assist_config\n    }\n    response {\n        result 0 : integer\n    }\n}\n\n\n"
